/* LCD_CAM Intel 8080 parallel bus (8 or 16 data lines) with DMA, and RGB (DPI) panels.
 * i80: command phase from a register, parameters/pixels by DMA. RGB: a frame buffer streamed in a loop
 * with HSYNC/VSYNC/DE timing generated by the controller. */
#pragma once
#include "ndf.h"

typedef struct {
    int8_t data[16];               /* D0..D(bits-1) */
    int8_t wr, dc, cs;             /* cs < 0: none */
    uint8_t bits;                  /* 8 or 16 */
    uint32_t pclk_hz;              /* 2.5 kHz .. 40 MHz (160 MHz / n) */
} lcd_i80_cfg_t;

uint32_t lcd_i80_init(const lcd_i80_cfg_t *c);              /* achieved WR clock, 0 on error */
/* cmd >= 0: one command cycle (DC low), then n bytes from data (DC high) by DMA. Blocks until sent.
 * data must be in internal RAM; n <= 32 KB per call. */
int      lcd_i80_send(int cmd, const void *data, size_t n);
/* Same, returns at once; lcd_i80_wait() blocks until done (or the next send waits). */
int      lcd_i80_send_async(int cmd, const void *data, size_t n);
void     lcd_i80_wait(void);

typedef struct {
    int8_t data[16], pclk, hsync, vsync, de;   /* de < 0: none */
    uint8_t bits;                  /* 8 or 16 */
    uint32_t pclk_hz;
    uint16_t width, height, hsw, hbp, hfp, vsw, vbp, vfp;   /* pixels / lines */
} lcd_rgb_cfg_t;
/* fb: width*height pixels (bits/8 bytes each) in internal RAM or PSRAM, streamed for ever. */
uint32_t lcd_rgb_start(const lcd_rgb_cfg_t *c, const void *fb);
void     lcd_rgb_stop(void);
uint32_t lcd_rgb_frames(void);                               /* VSYNC count since start */
